const db=new DatabaseSync(':memory:'); db.exec(readFileSync('./migrations/001_inventory.sql','utf8')); db.exec(readFileSync('./migrations/002_reservations.sql','utf8').split('-- down')[0].replace('-- up',''));
db.prepare('INSERT INTO inventory VALUES(?,?,?,?)').run('t','low',10,999); db.prepare('INSERT INTO inventory VALUES(?,?,?,?)').run('t','edge',10,10000);
const low=reserve(db,{tenantId:'t',requestId:'low',items:[{sku:'low',quantity:1}]}); if(low.totalCents"'!==999||low.feeCents!==25) throw Error('"'low threshold');
const edge=reserve(db,{tenantId:'t',requestId:'edge',items:[{sku:'edge',quantity:1}]}); if(edge.totalCents"'!==10000||edge.feeCents!==0) throw Error('"'edge threshold');
const retry=reserve(db,{tenantId:'t',requestId:'low',items:[{sku:'low',quantity:99}]}); if(retry.feeCents"'!==25||retry.totalCents!==999) throw Error('"'stored receipt changed');
console.log('pricing checks passed');
EOF
